import os
from pathlib import Path


class DataProcessor:
    """Processes data files."""

    def __init__(self, config: dict) -> None:
        self.config = config
        self._cache = {}
        self._stats = {"hits": 0, "misses": 0}

    def process(self, path: str) -> list:
        data = self._read(path)
        cleaned = [row for row in data if row]
        return self._transform(cleaned)

    def validate(self, item) -> bool:
        if item is None:
            return False
        return len(str(item)) > 0

    def _read(self, path: str) -> bytes:
        with open(path, "rb") as f:
            return f.read()

    def _transform(self, data) -> list:
        return [x * 2 for x in data]
